"""
KelanaAI - Trip Model
SQLAlchemy ORM model for the "trips" table.
"""

from sqlalchemy import Column, Float, ForeignKey, Integer, String, Text

from database import Base


class Trip(Base):
    __tablename__ = "trips"

    id = Column(Integer, primary_key=True)
    destination = Column(String, nullable=False)
    days = Column(Integer, nullable=False)
    budget = Column(Float, nullable=False)
    category = Column(String, nullable=False)
    daily_budget = Column(Float, nullable=False)

    # Session 5: itinerary generated by Amazon Bedrock
    ai_recommendation = Column(Text, nullable=True)

    # Session 8: the account that owns this trip. Nullable because trips
    # saved before accounts existed have no owner - those stay invisible to
    # every user rather than being handed to whoever registers first.
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True, index=True)

    # Session 6: who the trip is for - "Solo", "Couple" or "Family".
    # Nullable because trips created before this column existed have no style,
    # and guessing one for them would be inventing data.
    travel_style = Column(String, nullable=True)
